        FeeParams memory p,
        uint256 minFeeWei
    )
        internal
        pure
        returns (uint256 fee)
    {
        fee = feeGivenNet(net, R0, L, p);
        // Apply the min-fee on the total fee; gross = net + fee
        fee = _enforceMinFee(fee, net + fee, uint256(p.cRay), uint256(p.mRay), minFeeWei);
