//SPDX-License-Identifier: BUSL-1.1
pragma solidity >=0.8.28 <0.9.0;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import {
    ReentrancyGuardTransientUpgradeable
} from "@openzeppelin-upgradeable/contracts/utils/ReentrancyGuardTransientUpgradeable.sol";
import { SafeTransferLib } from "@solady/utils/SafeTransferLib.sol";
import { SafeCastLib } from "@solady/utils/SafeCastLib.sol";

import { FastLaneERC20 } from "./FLERC20.sol";
import { IShMonad } from "./interfaces/IShMonad.sol";
import { IMonadStaking } from "./interfaces/IMonadStaking.sol";
import { WorkingCapital, RevenueSmoother } from "./Types.sol";
import { NATIVE_TOKEN, SCALE, MONAD_EPOCH_LENGTH } from "./Constants.sol";

import { AccountingLib } from "./libraries/AccountingLib.sol";
import { CircuitBreakerLib as CBLib } from "./libraries/CircuitBreakerLib.sol";

import { PrecompileHelpers } from "./PrecompileHelpers.sol";

/// @author FastLane Labs
/// @dev Based on OpenZeppelin's ERC4626 implementation, with modifications to support ShMonad's storage structure.
abstract contract FastLaneERC4626 is FastLaneERC20, PrecompileHelpers, ReentrancyGuardTransientUpgradeable {
    using Math for uint256;
    using SafeCastLib for uint256;
    using SafeTransferLib for address;
    using AccountingLib for WorkingCapital;

    // --------------------------------------------- //
    //            ERC4626 Custom Functions           //
    // --------------------------------------------- //

    /// @notice Boosts yield by donating native MON to ShMonad holders.
    /// @dev Applies boost commission, records the net amount as earned revenue, and queues liquid MON for staking.
    /// @param yieldOriginator Address credited in events/analytics as the source of the yield boost.
    /// @custom:selector 0x4dc4993a
    function boostYield(address yieldOriginator) external payable nonReentrant cbPooledShareRate {
        _handleBoostYield(msg.value.toUint128());
        emit BoostYield(_msgSender(), yieldOriginator, 0, msg.value, false);
    }

    /// @notice Boosts yield by burning a specific address's shMON shares and donating the underlying value.
    /// @dev Converts `shares` to MON using the smoothed exit rate, spending allowance if `msg.sender != from`.
    /// The MON remains in the contract so the shares:assets ratio improves for all remaining holders.
    /// @param shares Amount of shMON to burn for the yield boost.
    /// @param from Address providing the shares that will be burned.
    /// @param yieldOriginator Address attributed as the source of the boost in emitted events.
    /// @custom:selector 0x5357a136
    function boostYield(uint256 shares, address from, address yieldOriginator) external nonReentrant cbPooledShareRate {
        // Share-burn boosts add to recent-revenue accounting without new MON entering the contract. Value them on the
        // same smoothed basis used by exits so the added offset cannot lower user-facing redeem/unstake quotes.
        uint256 _assets = _convertToAssets({
            shares: shares, rounding: Math.Rounding.Floor, deductRecentRevenue: true, deductMsgValue: false
        });

        if (from != _msgSender()) {
            _spendAllowance(from, _msgSender(), shares);
        }
        _burn(from, shares);

        _handleBoostYieldFromShares(_assets.toUint128());
        // emit event for extra yield
        emit BoostYield(from, yieldOriginator, 0, _assets, true);
        // Native tokens intentionally not sent - remains in ShMonad as yield
    }

    /// @notice Credits validator rewards (e.g., MEV) to StakeTracker, splitting protocol fee vs validator payout.
    /// @dev Caller must pass the validator ID for attribution; the fee portion is derived from `feeRate` (1e18 = 100%).
    /// @param validatorId The ID of the validator receiving attribution for the reward.
    /// @param feeRate The fee rate applied to the reward (scaled by 1e18).
    /// @custom:selector 0xe5cdc7c7
    function sendValidatorRewards(uint64 validatorId, uint256 feeRate) external payable nonReentrant cbPooledShareRate {
        require(feeRate <= SCALE, InvalidFeeRate(feeRate));
        (uint120 _validatorPayout, uint120 _feeTaken) = _handleValidatorRewards(validatorId, msg.value, feeRate);

        emit SendValidatorRewards(_msgSender(), validatorId, _validatorPayout, _feeTaken);
    }

    // --------------------------------------------- //
    //           ERC4626 Standard Functions          //
    // --------------------------------------------- //

    /// @dev See {IERC4626-deposit}.
    /// @notice Non-standard: this function is `public payable` (ERC-4626 specifies `external` & non-payable).
    /// Callers must send native MON equal to `assets` (`msg.value == assets`) or the call reverts. Integrations
    /// using a canonical IERC4626 interface should wrap MON (e.g., WMON) or call this entrypoint with value.
    /// @custom:selector 0x6e553f65
    function deposit(
        uint256 assets,
        address receiver
    )
        public
        payable
        virtual
        notWhenClosed
        nonReentrant
        cbPooledShareRate
        returns (uint256)
    {
        uint256 maxAssets = maxDeposit(receiver);
        require(assets <= maxAssets, ERC4626ExceededMaxDeposit(receiver, assets, maxAssets));

        uint256 shares = _previewDeposit(assets, true);
        _deposit(_msgSender(), receiver, assets, shares);

        return shares;
    }

    /// @dev See {IERC4626-mint}.
    ///
    /// @notice IMPORTANT: Callers must first call `previewMint(shares)` off-chain to determine the exact
    /// `msg.value` required. The function will revert if `msg.value` does not exactly match the calculated
    /// asset amount based on the current exchange rate.
    ///
    /// The exchange rate used by `_previewMint()` depends on the current on-chain state (total assets and
    /// total supply), so the required `msg.value` cannot be known without querying `previewMint()` first.
    ///
    /// Example usage:
    /// ```
    /// uint256 requiredAssets = vault.previewMint(desiredShares);
    /// vault.mint{value: requiredAssets}(desiredShares, receiver);
    /// ```
    ///
    /// @param shares The amount of shares to mint
    /// @param receiver The address that will receive the minted shares
    /// @return assets The amount of assets deposited (equal to msg.value)
    /// @custom:selector 0x94bf804d
    function mint(
        uint256 shares,
        address receiver
    )
        public
        payable
        virtual
        notWhenClosed
        nonReentrant
        cbPooledShareRate
        returns (uint256)
    {
        uint256 maxShares = maxMint(receiver);
        require(shares <= maxShares, ERC4626ExceededMaxMint(receiver, shares, maxShares));

        uint256 assets = _previewMint(shares, true);
        _deposit(_msgSender(), receiver, assets, shares);

        return assets;
    }

